sql:
SELECT arrayReduce(
    ('countResample', (x, y) -> (x + y)),
    arrayMap(
        i -> i,
        range(0, 3)
    ),
    groupArray(
        (x, y) -> (x, y),
        groupArrayDistinct(
            (toHour(timestamp) div 6) * 6
        )
    )
) FROM events

